(() => {
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const A=window.STORY_ART||{assets:{},byStory:{},scenes:{},meta:{}};
 const shown=new Map();let active=null,opener=null;
 const asset=key=>A.assets[String(key||'').toLowerCase()];
 const scene=id=>A.scenes[id];
 const items=s=>A.byStory[typeof s==='string'?s:s.id]||[];
 function attributes(u,storyId){return `data-cg-key="${esc(u.key)}" data-cg-story="${esc(storyId)}" data-cg-phase="${u.phase??0}" data-cg-scene="${esc(u.sceneId)}" data-cg-caption="${esc(u.caption||'')}"`;}
 function figure(u,storyId,phase){const im=asset(u.key),s=scene(u.sceneId);if(!im||!s)return '';return `<figure class="event-figure ${im.height>im.width?'is-portrait':''}"><button class="story-image-button" ${attributes({...u,phase},storyId)} aria-label="放大${u.type==='background'?'剧情场景图':'剧情CG'}：${esc(u.caption)}"><img src="${esc(im.src)}" alt="${esc(u.caption)}" width="${im.width}" height="${im.height}" loading="lazy" decoding="async"><span class="image-zoom-label">点击放大 ⤢</span></button><figcaption><div class="cg-caption-type">${u.type==='background'?'游戏剧情场景图':'游戏剧情 CG'}</div><p>${esc(u.caption)}</p><div class="cg-source-links"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a><a href="${esc(im.sourceImage)}" target="_blank" rel="noopener noreferrer">原始 PNG · ${im.width}×${im.height} ↗</a><a href="${esc(im.sourcePage)}" target="_blank" rel="noopener noreferrer">图像出处 ↗</a></div></figcaption></figure>`;}
 function grid(storyId){const all=items(storyId),count=shown.get(storyId)||12;return `<div class="cg-gallery-grid">${all.slice(0,count).map((u,i)=>{const im=asset(u.key),s=scene(u.sceneId);return `<article class="cg-gallery-card"><button ${attributes(u,storyId)} aria-label="查看剧情CG ${i+1}：${esc(s.label)}"><img src="${esc(im.thumb)}" alt="${esc(s.label)}中的剧情插图" loading="lazy" decoding="async" width="420" height="236"><span>${String(i+1).padStart(2,'0')} / ${String(all.length).padStart(2,'0')}</span></button><p>${esc(s.label)}</p><a href="#/story/${storyId}/part-${u.phase}">对应事件 ↗</a></article>`;}).join('')}</div>${count<all.length?`<button class="cg-load-more" data-cg-more="${storyId}">继续显示 · 余 ${all.length-count} 张 <span>＋</span></button>`:'<p class="cg-gallery-end">本篇已收录画面已全部显示。</p>'}`;}
 function gallery(s){const all=items(s);if(!all.length)return '';return `<details class="story-cg-gallery" id="story-cg-gallery"><summary><span>本篇剧情图册</span><b>${all.length} 张 CG 与剧情插图</b></summary><p class="cg-gallery-note">按正文引用的章节与阶段归类。部分画面出自回忆或记录，具体时点以正文说明为准。点击查看原生尺寸高清图，也可打开原始 PNG。</p><div class="cg-gallery-content" data-cg-gallery="${s.id}">${grid(s.id)}</div></details>`;}
 function preview(s,phase){const p=s.chronicle?.periods[phase],u=p?.illustrations?.find(x=>asset(x.key))||items(s).find(x=>x.phase===phase);if(!u)return '';const im=asset(u.key),explicit=p?.illustrations?.some(x=>x.key===u.key);return `<a class="map-cg-preview" href="#/story/${s.id}/${explicit?'part-'+phase:'story-cg-gallery'}"><img src="${esc(im.thumb)}" alt="${esc(u.caption||scene(u.sceneId)?.label)}" loading="lazy" decoding="async"><span>${explicit?'阅读图文事件':'查看本篇剧情图册'} <b>↗</b></span></a>`;}
 const dialog=document.createElement('dialog');dialog.id='story-cg-dialog';dialog.setAttribute('aria-label','剧情CG大图');dialog.innerHTML='<div class="cg-dialog-top"><span class="cg-dialog-count"></span><button class="cg-dialog-close" aria-label="关闭剧情CG大图">关闭 ×</button></div><div class="cg-dialog-stage"><button data-cg-direction="-1" aria-label="上一张剧情CG">‹</button><img alt=""><button data-cg-direction="1" aria-label="下一张剧情CG">›</button></div><div class="cg-dialog-caption"></div>';document.body.append(dialog);
 function paint(){const u=active.items[active.index],im=asset(u.key),s=scene(u.sceneId);dialog.querySelector('.cg-dialog-stage img').src=im.src;dialog.querySelector('.cg-dialog-stage img').width=im.width;dialog.querySelector('.cg-dialog-stage img').height=im.height;dialog.querySelector('.cg-dialog-stage img').alt=u.caption||s.label;dialog.querySelector('.cg-dialog-count').textContent=`${active.index+1} / ${active.items.length} · 游戏剧情图像`;dialog.querySelector('[data-cg-direction="-1"]').disabled=active.index===0;dialog.querySelector('[data-cg-direction="1"]').disabled=active.index===active.items.length-1;dialog.querySelector('.cg-dialog-caption').innerHTML=`${u.caption?`<p>${esc(u.caption)}</p>`:''}<div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a><a href="${esc(im.sourceImage)}" target="_blank" rel="noopener noreferrer">原始 PNG · ${im.width}×${im.height} ↗</a><a href="${esc(im.sourcePage)}" target="_blank" rel="noopener noreferrer">图像出处 ↗</a><a data-cg-return href="#/story/${active.storyId}/part-${u.phase}">阅读对应事件 ↗</a></div>`;}
 function open(button){const u={key:button.dataset.cgKey,phase:Number(button.dataset.cgPhase),sceneId:button.dataset.cgScene,caption:button.dataset.cgCaption},storyId=button.dataset.cgStory,all=items(storyId).map(x=>({...x}));let i=all.findIndex(x=>x.key.toLowerCase()===u.key.toLowerCase());if(i<0){all.unshift(u);i=0;}else all[i]=u;active={storyId,items:all,index:i};opener=button;paint();dialog.showModal();}
 function move(n){if(!active)return;active.index=Math.max(0,Math.min(active.items.length-1,active.index+n));paint();}
 document.addEventListener('click',e=>{const more=e.target.closest('[data-cg-more]');if(more){const id=more.dataset.cgMore;shown.set(id,(shown.get(id)||12)+12);document.querySelector(`[data-cg-gallery="${id}"]`).innerHTML=grid(id);return;}const button=e.target.closest('[data-cg-key]');if(button)open(button);const direction=e.target.closest('[data-cg-direction]');if(direction)move(Number(direction.dataset.cgDirection));if(e.target.closest('.cg-dialog-close,[data-cg-return]')||e.target===dialog)dialog.close();});
 document.addEventListener('keydown',e=>{if(!dialog.open)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowLeft'?-1:1);}});
 dialog.addEventListener('close',()=>{if(opener?.isConnected)opener.focus();active=null;});
 window.STORY_IMAGE_UI={asset,items,figure,gallery,preview};
})();
